/// Render the full bindings file.
///
/// # Errors
/// [`BindingsError::Export`] when a type cannot be expressed in TypeScript.
pub fn render() -> Result<String, BindingsError> {
    // Floats cross by wasm-bindgen, which keeps NaN and Infinity as numbers, so f64 is
    // `number`, not the `number | null` a JSON round trip would need.
    let floats = specta_typescript::semantic::Configuration::empty().enable_lossless_floats();
    let types = types().map(|mut ndt| {
        if let Some(ty) = ndt.ty.as_mut() {
            drop_skipped_none(ty);
        }
        ndt
    });
    Ok(Typescript::default()
        .header(HEADER)
        .export(&floats.apply_types(&types), specta_serde::Format)?)
}

/// serde attribute key specta records for `skip_serializing_if`.
const SKIP_IF: &str = "serde:field:skip_serializing_if";

/// A field with `skip_serializing_if = "Option::is_none"` is never `null` on the way
/// out, and a missing key reads as `None` on the way in, so `x?: T` is exact where
/// specta's unified shape says `x?: T | null`. Fields that only have `default` keep
/// `| null`, because `null` means something there (for example "clear").
fn drop_skipped_none(ty: &mut specta::datatype::DataType) {
    use specta::datatype::{DataType, Fields};
    let fields: Vec<&mut specta::datatype::Field> = match ty {
        DataType::Struct(s) => fields_mut(&mut s.fields),
        DataType::Enum(e) => e
            .variants
            .iter_mut()
            .flat_map(|(_, v)| fields_mut(&mut v.fields))
            .collect(),
        _ => return,
    };
    for field in fields {
        let is_none_skip = field
            .attributes
            .get_named_as::<String>(SKIP_IF)
            .is_some_and(|p| p == "Option::is_none");
        if is_none_skip
            && matches!(field.ty, Some(DataType::Nullable(_)))
            && let Some(DataType::Nullable(inner)) = field.ty.take()
        {
            field.ty = Some(*inner);
        }
        if let Some(other) = field.ty.as_mut() {
            drop_skipped_none(other);
        }
    }

    fn fields_mut(fields: &mut Fields) -> Vec<&mut specta::datatype::Field> {
        match fields {
            Fields::Unit => Vec::new(),
            Fields::Unnamed(u) => u.fields.iter_mut().collect(),
            Fields::Named(n) => n.fields.iter_mut().map(|(_, f)| f).collect(),
        }
    }
}

/// What the binary was asked to do.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    /// Write the bindings file.
    Write,
    /// Fail if the file on disk differs from a fresh render.
    Check,
}

/// Parse CLI args (without the program name). `None` for anything but no args or exactly `--check`.
#[must_use]
pub fn parse_mode(args: &[String]) -> Option<Mode> {
    match args {
        [] => Some(Mode::Write),
        [a] if a == "--check" => Some(Mode::Check),
        _ => None,
    }
}

/// True when `path` holds exactly the rendered bindings. A missing file is stale (false).
///
/// # Errors
/// [`BindingsError::Export`] when rendering fails; [`BindingsError::Io`] for any read error other than not found.
pub fn is_fresh(path: &std::path::Path) -> Result<bool, BindingsError> {
    let fresh = render()?;
    match std::fs::read_to_string(path) {
        Ok(current) => Ok(current == fresh),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(source) => Err(BindingsError::Io {
            path: path.to_path_buf(),
            source,
        }),
    }
}

/// Write the rendered bindings to `path`, creating parent directories.
///
/// # Errors
/// [`BindingsError::Export`] when rendering fails; [`BindingsError::Io`] when a directory or the file cannot be written.
pub fn write(path: &std::path::Path) -> Result<(), BindingsError> {
    let fresh = render()?;
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir).map_err(|source| BindingsError::Io {
            path: dir.to_path_buf(),
            source,
        })?;
    }
    std::fs::write(path, fresh).map_err(|source| BindingsError::Io {
        path: path.to_path_buf(),
        source,
    })
}

