#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn render_starts_with_header() {
        let out = render().unwrap();
        assert!(out.starts_with(HEADER));
    }

    #[test]
    fn render_exports_core_info() {
        let out = render().unwrap();
        assert!(out.contains("export type CoreInfo"));
        assert!(out.contains("version: string"));
        assert!(out.contains("export type TokenizerOptions"));
        assert!(out.contains("splitCamelCase: boolean"));
    }

    #[test]
    fn skipped_none_fields_are_not_nullable() {
        let out = render().unwrap();
        let start = out.find("export type OpenAccessCandidate").unwrap();
        let body = &out[start..start + out[start..].find("\n}").unwrap()];
        assert!(body.contains("license?: string,"), "{body}");
        assert!(!body.contains("| null"), "{body}");
    }

    #[test]
    fn default_only_fields_keep_null() {
        // ImagePlacementPatch.crop: absent keeps, null clears.
        let out = render().unwrap();
        let start = out.find("export type ImagePlacementPatch").unwrap();
        let body = &out[start..start + out[start..].find("\n}").unwrap()];
        assert!(
            body.contains("crop?: [number, number, number, number] | null"),
            "{body}"
        );
    }

    #[test]
    fn render_is_deterministic() {
        assert_eq!(render().unwrap(), render().unwrap());
    }

    fn scratch(name: &str) -> std::path::PathBuf {
        let dir = std::env::temp_dir().join(format!("wf-bindings-{}-{name}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    fn args(list: &[&str]) -> Vec<String> {
        list.iter().map(|s| (*s).to_owned()).collect()
    }

    #[test]
    fn parse_mode_accepts_no_args_and_check_only() {
        assert_eq!(parse_mode(&args(&[])), Some(Mode::Write));
        assert_eq!(parse_mode(&args(&["--check"])), Some(Mode::Check));
        assert_eq!(parse_mode(&args(&["--chek"])), None);
        assert_eq!(parse_mode(&args(&["--check", "x"])), None);
    }

    #[test]
    fn is_fresh_missing_file_is_stale() {
        let dir = scratch("missing");
        let ok = is_fresh(&dir.join("bindings.ts")).unwrap();
        let _ = std::fs::remove_dir_all(&dir);
        assert!(!ok);
    }

    #[test]
    fn is_fresh_different_bytes_is_stale() {
        let dir = scratch("different");
        let file = dir.join("bindings.ts");
        std::fs::write(&file, "stale").unwrap();
        let ok = is_fresh(&file).unwrap();
        let _ = std::fs::remove_dir_all(&dir);
        assert!(!ok);
    }

    #[test]
    fn write_creates_nested_parent_and_is_then_fresh() {
        let dir = scratch("nested");
        let file = dir.join("a").join("b").join("bindings.ts");
        write(&file).unwrap();
        let ok = is_fresh(&file).unwrap();
        let _ = std::fs::remove_dir_all(&dir);
        assert!(ok);
    }

    #[test]
    fn is_fresh_on_directory_is_io_error() {
        let dir = scratch("is-dir");
        let result = is_fresh(&dir);
        let _ = std::fs::remove_dir_all(&dir);
        assert!(matches!(result, Err(BindingsError::Io { .. })));
    }
}
